def _expand(lines, qa_scope="الاختبار المستقل والحكم بيمر أو لا يمر على كل مخرج قبل أن يصل إلى صاحب المشروع"):
    out = []
    for ln in lines:
        n, t, sc = [x.strip() for x in ln.split("|")]
        out.append((n, t, sc, "Claude"))
    out.append((QA_NAME, "الاختبار المستقل والحكم", qa_scope, "Claude"))
    return out


