def commands_library_md(team):
    out = "# مكتبة الأوامر\n\nأوامر جاهزة للنسخ. تُحدَّث تلقائيًا عند إضافة دور.\n\n"
    for g in commands_library(team):
        out += "## %s\n\n%s\n\n" % (g["title"], g.get("hint", ""))
        for it in g["items"]:
            out += "**%s**\n\n```\n%s\n```\n\n" % (it["label"], it["text"])
    return out


# ---------------------------------------------------------------- مساعدات


def now():
    return dt.datetime.now(TZ)


DATE_STYLE = "dmy"  # dmy: «26 أكتوبر 2026»، ymd: «2026年10月26日» (الصينية)
DAY_DOT = ""  # نقطة بعد اليوم في الألمانية: «26. Oktober 2026»


def fmt_date(d):
    if DATE_STYLE == "ymd":
        return "%d\u5e74%d\u6708%d\u65e5" % (d.year, d.month, d.day)
    return "%d%s %s %d" % (d.day, DAY_DOT, MONTHS[d.month - 1], d.year)


def date_rx():
    """تعبير تاريخ التسمية المعتمدة في اللغة (مجموعات ثلاث)، وdate_ymd يحوّل مطابقته إلى (سنة، شهر، يوم)."""
    if DATE_STYLE == "ymd":
        return r"(\d{4})\u5e74(\d{1,2})\u6708(\d{1,2})\u65e5"
    return r"(\d{1,2})%s\s+(%s)\s+(\d{4})" % (re.escape(DAY_DOT), "|".join(MONTHS))


def date_ymd(m):
    if DATE_STYLE == "ymd":
        return int(m.group(1)), int(m.group(2)), int(m.group(3))
    return int(m.group(3)), MONTHS.index(m.group(2)) + 1, int(m.group(1))


def fmt_dt(d):
    return "%s، %s" % (fmt_date(d), d.strftime("%H:%M"))


def pm_name(roster):
    """صاحب المرجع: «رئيس المنتج» إن وُجد، وإلا أول دور غير البوصلة وغير ضمان الجودة."""
    names = [r["name"] for r in roster]
    if "رئيس المنتج" in names:
        return "رئيس المنتج"
    for r in roster:
        if r["id"] != "compass" and r["name"] != QA_NAME:
            return r["name"]
    return COMPASS


def fill(t, **kw):
    for k, v in kw.items():
        t = t.replace("{{" + k + "}}", str(v))
    return t


def clean_name(s):
    s = re.sub(r'[\\/:*?"<>|\x00-\x1f]', " ", s).replace("_", " ")
    return re.sub(r"\s+", " ", s).strip()


def norm(s):
    return re.sub(r"[\u064B-\u065F\u0640]", "", str(s or "")).strip()


def role_key(s):
    s = norm(s)
    s = re.sub(r"^\d+\.\s*", "", s)
    s = s.replace("«", "").replace("»", "").replace('"', "")
    return s.split(":")[0].strip()


def atomic_write(path, text):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + ".tmp")
    tmp.write_text(text, encoding="utf-8")
    os.replace(tmp, path)


def write_new(path, text, report=None):
    """ينشئ الملف إن لم يوجد، ولا يكتب فوق موجود أبدًا."""
    path = Path(path)
    if path.exists():
        if report is not None:
            report.append(("تُرك", path))
        return False
    atomic_write(path, text)
    if report is not None:
        report.append(("أُنشئ", path))
    return True


def terminal_label(value):
    """Use English catalogue labels in the CLI; leave user-authored values intact."""
    if LOCAL is not None:
        return value
    if not hasattr(terminal_label, "catalogue"):
        wizard = load_wizard()
        match = re.search(r"\bvar CAT\s*=\s*", wizard)
        terminal_label.catalogue = json.JSONDecoder().raw_decode(wizard[match.end():])[0] if match else {}
    return terminal_label.catalogue.get(value, value)


def terminal_diagnostic(text):
    """Translate application diagnostics; preserve project names and user-authored values."""
    templates = [
        ("اسم فيه شرطة سفلية: %s", "Name contains an underscore: %s"),
        ("لا يوجد %s في الفريق: لا يمكن ضمان أن مخرجًا يصل إلى %s بحكم مستقل", "Missing %s in the team: independent quality review for %s cannot be guaranteed"),
        ("ملف الدور ناقص: %s", "Missing role file: %s"),
        ("ترقيم اللوحة مكرر أو غير مرتب", "Board row numbers are duplicated or out of order"),
        ("الترقيم يجب أن يبدأ من 1", "Row numbering must start at 1"),
        ("الصف %d: اسم غير معروف «%s»", "Row %d: unknown team member %s"),
        ("الصف %d: حالة غير معتمدة «%s»", "Row %d: invalid status %s"),
        ("الصف %d: يبدأ بعد صف غير موجود %s", "Row %d: missing dependency %s"),
        ("%s: %d صفوف مفتوحة (السقف 5)", "%s: %d open rows (limit 5)"),
        ("القرارات المعلقة %d (السقف %d)", "%d pending decisions (limit %d)"),
        ("القرار المعلق %d تجاوز %d ساعة: يؤخذ بالتوصية ويُسجَّل بـ decide", "Pending decision %d is over %d hours old: follow the recommendation and record it with decide"),
    ]
    for source, target in templates:
        pattern = "(.*?)".join(re.escape(part) for part in re.split(r"%[sd]", source))
        match = re.fullmatch(pattern, text, re.S)
        if match:
            values = iter(match.groups())
            return re.sub(r"%[sd]", lambda _: next(values), target)
    return text


def die(msg, code=1):
    print(msg, file=sys.stderr)
    sys.exit(code)


def find_root(start=None):
    cands = []
    if start:
        cands.append(Path(start).resolve())
    cands.append(Path.cwd().resolve())
    cands.append(Path(__file__).resolve().parent)
    for c in cands:
        for p in [c] + list(c.parents):
            if (p / "Agents" / "Team.json").exists():
                code = json.loads((p / "Agents" / "Team.json").read_text(encoding="utf-8")).get("lang_code") or "ar"
                if code != (LOCAL or "ar"):
                    die("This project works in a different language (%s). Use the tool inside the project: %s" % (code, p / "Tools" / TOOL_NAME))
                return p
    die("No project found (Agents/Team.json is missing). Run from the project folder or pass --root.")


def load_team(root):
    return json.loads((root / "Agents" / "Team.json").read_text(encoding="utf-8"))


def save_team(root, team):
    atomic_write(root / "Agents" / "Team.json", json.dumps(team, ensure_ascii=False, indent=2) + "\n")


# ---------------------------------------------------------------- الجداول والأقسام


def split_row(line):
    s = line.strip()
    if s.startswith("|"):
        s = s[1:]
    if s.endswith("|") and not s.endswith("\\|"):
        s = s[:-1]
    s = s.replace("\\|", "\x00")
    return [c.strip().replace("\x00", "|") for c in s.split("|")]


def esc_cell(v):
    return str(v).replace("|", "\\|").replace("\n", " ").strip() or "—"


def section_range(lines, n):
    start = None
    for i, ln in enumerate(lines):
        if re.match(r"^##\s+%d\.\s" % n, ln):
            start = i
            break
    if start is None:
        return None
    end = len(lines)
    for j in range(start + 1, len(lines)):
        if re.match(r"^##\s", lines[j]):
            end = j
            break
    return start, end


def parse_table(lines):
    rows, header = [], None
    for ln in lines:
        if not ln.strip().startswith("|"):
            continue
        cells = split_row(ln)
        if all(re.fullmatch(r":?-{2,}:?", c) for c in cells if c):
            continue
        if header is None:
            header = cells
            continue
        rows.append(dict(zip(header, cells + [""] * (len(header) - len(cells)))))
    return rows


def parse_items(lines):
    items, cur = [], None
    for ln in lines:
        m = re.match(r"^(\d+)\.\s+(.*)$", ln)
        if m:
            cur = {"n": int(m.group(1)), "text": m.group(2).strip()}
            items.append(cur)
        elif cur is not None and ln[:1] in (" ", "\t") and ln.strip():
            cur["text"] += "\n" + ln.strip()
    return items


def read_board(root):
    text = (root / "Agents" / "Board.md").read_text(encoding="utf-8")
    lines = text.splitlines()
    out = {"text": text, "lines": lines, "tasks": [], "decisions": [], "circulars": [], "team": []}
    r = section_range(lines, 1)
    if r:
        out["decisions"] = parse_items(lines[r[0] + 1:r[1]])
    r = section_range(lines, 2)
    if r:
        out["circulars"] = parse_items(lines[r[0] + 1:r[1]])
    r = section_range(lines, 3)
    if r:
        for d in parse_table(lines[r[0] + 1:r[1]]):
            num = re.sub(r"\D", "", d.get("#", ""))
            if num:
                out["tasks"].append({
                    "n": int(num), "from": d.get("من", ""), "to": d.get("إلى", ""), "task": d.get("المهمة", ""),
                    "inputs": d.get("المدخلات", ""), "output": d.get("المخرج", ""), "after": d.get("يبدأ بعد", ""),
                    "due": d.get("الموعد", ""), "status": d.get("الحالة", ""), "next": d.get("للتالي", "")})
    r = section_range(lines, 4)
    if r:
        out["team"] = parse_table(lines[r[0] + 1:r[1]])
    return out


def is_done(status):
    s = norm(status)
    return s.startswith("مسلم") or s.startswith("معتمد")


def ready_tasks(tasks, role):
    by_n = {t["n"]: t for t in tasks}
    res = []
    for t in tasks:
        if role_key(t["to"]) != role_key(role) or norm(t["status"]) != "محالة":
            continue
        deps = [int(x) for x in re.findall(r"\d+", t["after"] or "")]
        if all(d in by_n and is_done(by_n[d]["status"]) for d in deps):
            res.append(t)
    return res


def touch_updated(text, by):
    return re.sub(r"^\*\*آخر تحديث:\*\*.*$", "**آخر تحديث:** %s، %s" % (fmt_dt(now()), by), text, count=1, flags=re.M)


